BEGIN;
DO $$ DECLARE a uuid;s uuid;s2 uuid;m uuid;team uuid;doc jsonb;first jsonb;result jsonb;rev integer;BEGIN
 INSERT INTO public.admin_users(email,password_hash,role,is_active)VALUES('fictional-member-write@example.test','fictional-proof','admin',true)RETURNING id INTO a;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash)VALUES(a,repeat('1',64))RETURNING id INTO s;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash)VALUES(a,repeat('2',64))RETURNING id INTO s2;
 INSERT INTO public.admin_teams(name,slug)VALUES('Fictional member write scope','fictional-member-write-scope')RETURNING id INTO team;
 doc:=jsonb_build_object('record',jsonb_build_object('name','Fictional original member','email','fictional-original-member@example.test','phone','','year','','major','','category','member','interests','[]'::jsonb,'is_active',true,'is_core_team',false,'team_section','Active Members'),'teamId',team);
 result:=public.inspect_community_member_write(a,s,NULL,'create',NULL,doc,repeat('3',64),repeat('4',64));IF(result->>'committed')::boolean OR NOT(result->>'canRetry')::boolean OR EXISTS(SELECT 1 FROM public.members WHERE email='fictional-original-member@example.test') THEN RAISE EXCEPTION 'Member inspection wrote content';END IF;
 first:=public.mutate_community_member_write(a,s,NULL,NULL,'create',NULL,doc,repeat('3',64),repeat('4',64),NULL);m:=(first->>'id')::uuid;rev:=(first->>'revision')::integer;
 result:=public.mutate_community_member_write(a,s,NULL,NULL,'create',NULL,doc,repeat('3',64),repeat('4',64),NULL);IF result<>first OR(SELECT count(*) FROM public.members WHERE email='fictional-original-member@example.test')<>1 THEN RAISE EXCEPTION 'Member create duplicated';END IF;
 result:=public.inspect_community_member_write(a,s,NULL,'create',NULL,doc,repeat('3',64),repeat('4',64));IF NOT(result->>'committed')::boolean OR result::text LIKE '%Fictional original member%' OR result::text LIKE '%@%' THEN RAISE EXCEPTION 'Member receipt missing or disclosed fields';END IF;
 result:=public.inspect_community_member_write(a,s2,NULL,'create',NULL,doc,repeat('3',64),repeat('4',64));IF(result->>'committed')::boolean THEN RAISE EXCEPTION 'Member receipt crossed sessions';END IF;
 BEGIN PERFORM public.inspect_community_member_write(a,s,NULL,'create',NULL,doc,repeat('3',64),repeat('5',64));RAISE EXCEPTION 'Member body changed';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'CONFLICT' THEN RAISE;END IF;END;
 doc:=jsonb_build_object('action','update','revision',rev,'record',doc->'record'||jsonb_build_object('name','Fictional updated member'));
 first:=public.mutate_community_member_write(a,s,NULL,m,'update',rev,doc,repeat('6',64),repeat('7',64),NULL);
 UPDATE public.members SET name='Fictional later member',revision=revision+1 WHERE id=m;
 result:=public.mutate_community_member_write(a,s,NULL,m,'update',rev,doc,repeat('6',64),repeat('7',64),NULL);IF result<>first OR(SELECT name FROM public.members WHERE id=m)<>'Fictional later member' THEN RAISE EXCEPTION 'Accepted old member retry overwrote newer state';END IF;
 result:=public.inspect_community_member_write(a,s,m,'update',rev,doc,repeat('8',64),repeat('9',64));IF(result->>'canRetry')::boolean THEN RAISE EXCEPTION 'New stale member write allowed';END IF;
 UPDATE public.admin_teams SET is_active=false WHERE id=team;
 BEGIN PERFORM public.inspect_community_member_write(a,s,m,'update',rev,doc,repeat('6',64),repeat('5',64));RAISE EXCEPTION 'Current authority failed before receipt hash';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 UPDATE public.admin_teams SET is_active=true WHERE id=team;UPDATE public.admin_sessions SET revoked_at=now() WHERE id=s;
 BEGIN PERFORM public.inspect_community_member_write(a,s,m,'update',rev,doc,repeat('6',64),repeat('7',64));RAISE EXCEPTION 'Revoked session read receipt';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'NOT_FOUND' THEN RAISE;END IF;END;
 IF has_function_privilege('anon','public.inspect_community_member_write(uuid,uuid,uuid,text,integer,jsonb,text,text)','EXECUTE') OR has_function_privilege('authenticated','public.mutate_community_member_write(uuid,uuid,text,uuid,text,integer,jsonb,text,text,uuid)','EXECUTE') OR NOT has_function_privilege('service_role','public.inspect_community_member_write(uuid,uuid,uuid,text,integer,jsonb,text,text)','EXECUTE') THEN RAISE EXCEPTION 'Member write grants incorrect';END IF;
END $$;
DO $$ DECLARE a uuid;s uuid;m uuid;canonical uuid;doc jsonb;result jsonb;rev integer;reference text;first jsonb;BEGIN
 INSERT INTO public.admin_users(email,password_hash,role,is_active)VALUES('fictional-member-lifecycle@example.test','fictional-proof','admin',true)RETURNING id INTO a;
 INSERT INTO public.admin_sessions(admin_user_id,token_hash)VALUES(a,repeat('a',64))RETURNING id INTO s;
 INSERT INTO public.members(name,email,is_active,deleted_at)VALUES('Fictional restore source','fictional-restore-source@example.test',false,now())RETURNING id,revision INTO m,rev;
 reference:='MEM-'||upper(replace(m::text,'-',''));doc:=jsonb_build_object('action','restore','revision',rev,'confirmation',reference);
 BEGIN PERFORM public.mutate_community_member_write(a,s,NULL,m,'restore',rev,doc,repeat('b',64),repeat('c',64),NULL);RAISE EXCEPTION 'Unaccepted lifecycle bypassed password proof';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'VALIDATION_ERROR' THEN RAISE;END IF;END;
 first:=public.mutate_community_member_write(a,s,'fictional-proof',m,'restore',rev,doc,repeat('b',64),repeat('c',64),NULL);
 IF(SELECT deleted_at IS NOT NULL OR is_active FROM public.members WHERE id=m)THEN RAISE EXCEPTION 'Restore changed inactive semantics';END IF;
 result:=public.mutate_community_member_write(a,s,NULL,m,'restore',rev,doc,repeat('b',64),repeat('c',64),NULL);IF result<>first THEN RAISE EXCEPTION 'Accepted restore recovery required retained proof or mutated';END IF;
 UPDATE public.members SET is_active=true WHERE id=m;SELECT revision INTO rev FROM public.members WHERE id=m;
 doc:=jsonb_build_object('action','sync_profile','revision',rev,'confirmation',reference);
 first:=public.mutate_community_member_write(a,s,'fictional-proof',m,'sync_profile',rev,doc,repeat('d',64),repeat('e',64),NULL);
 IF(SELECT count(*) FROM public.team_members WHERE member_id=m)<>1 OR EXISTS(SELECT 1 FROM public.team_members WHERE member_id=m AND is_active)THEN RAISE EXCEPTION 'Sync did not create one unpublished profile';END IF;
 result:=public.mutate_community_member_write(a,s,NULL,m,'sync_profile',rev,doc,repeat('d',64),repeat('e',64),NULL);IF result<>first OR(SELECT count(*) FROM public.team_members WHERE member_id=m)<>1 THEN RAISE EXCEPTION 'Profile replay duplicated';END IF;
 INSERT INTO public.members(name,email)VALUES('Fictional canonical retained','fictional-canonical-retained@example.test')RETURNING id INTO canonical;
 UPDATE public.members SET is_active=false,deleted_at=now(),merged_into_id=canonical,revision=revision+1 WHERE id=m;SELECT revision INTO rev FROM public.members WHERE id=m;
 doc:=jsonb_build_object('action','unmerge','revision',rev,'confirmation',reference);
 first:=public.mutate_community_member_write(a,s,'fictional-proof',m,'unmerge',rev,doc,repeat('f',64),repeat('1',64),NULL);
 IF(SELECT merged_into_id IS NOT NULL OR deleted_at IS NOT NULL OR is_active FROM public.members WHERE id=m)THEN RAISE EXCEPTION 'Unmerge changed inactive recovery';END IF;
 result:=public.mutate_community_member_write(a,s,NULL,m,'unmerge',rev,doc,repeat('f',64),repeat('1',64),NULL);IF result<>first THEN RAISE EXCEPTION 'Unmerge replay mutated';END IF;
 UPDATE public.idempotency_keys SET expires_at=now()-interval '1 second' WHERE scope='member-write:'||a||':'||s||':unmerge:'||m;
 BEGIN PERFORM public.inspect_community_member_write(a,s,m,'unmerge',rev,doc,repeat('f',64),repeat('1',64));RAISE EXCEPTION 'Expired member receipt returned';EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'INVALID_STATE' THEN RAISE;END IF;END;
END $$;

ROLLBACK;
